# ORIGINAL: ARGINL's gate (lk-channel evidence/ARGINL/handoff.md) — `arg/3` inline in a clause body (`B_ARG_CF`, `B_ARG_VF`) against swipl 10.1.19; the rows are this file's own, generated by lk-channel evidence/ARGINL/gen_arg_rows.py
# test/core_lang/test_arg_body_swipl.jl — pl-comp.c `compileBodyArg3` (the inline form of `arg(Int, Var, FirstVar)` and `arg(Var, Var, FirstVar)`),
# the run loop's `B_ARG_CF`, `B_ARG_VF`, `arg3_fast`, `arg3_slow` (pl-vmi.c), the decompiler's read-back of both (pl-comp.c decompileBodyNoShift)
# and the `vmi_builtin` flag that switches the inline form off (every call then goes through arg/3 as a predicate):
#   * A PROGRAM consulted by the kernel's loader — user clauses whose bodies hold an arg/3 goal of each shape — and cases `t_<id>(R)` run IN
#     ORDER in one database, each wrapped in `catch(Goal, error(SsuE, _), R = raised(SsuE))`; `g_*` rows run the clauses, `o_*` rows run the
#     same goals under `vmi_builtin` false, `rb_*` rows read the clauses back with clause/2, `inf_*` rows count the inference the inline form saves.
#   * Every answer line is swipl's, PINNED (swipl 10.1.19-1-gcbf4e189, this program and driver, 2026-11-02, two runs byte-identical;
#     lk-channel evidence/ARGINL/arg_rows.out); with `swipl` on PATH the live answers are compared with the pins too.
#   * UNVERIFIED on the kernel: gate decides (a mismatch is traced to its upstream cause, not re-pinned).
using Test, LogicKernel
const LK = LogicKernel

# TERM TYPES PER CHUNK: REFERENCE — the inline arg/3 (src/pl-comp.jl, src/pl-wam.jl), built on the term layer; every type in CI and at milestones
include(joinpath(@__DIR__, "..", "term_under_test.jl"))
const _AG = lk_term_type(Union{Int64, Float64, String, BigInt, Rational{BigInt}})
_ags(x) = lk_sym(_AG, Symbol(x))

"A term as the driver's `enc/1` writes it: `V<i>` by first occurrence, atoms by name, compounds `name(args)`."
function _ag_enc(t::_AG, seen::Vector{UInt64}=UInt64[])::String
    k = kind(t)
    if k === VAR
        i = findfirst(==(var_key(t)), seen)
        if i === nothing
            push!(seen, var_key(t))
            i = length(seen)
        end
        return "V$(i - 1)"
    elseif k === SYM
        return is_nil(t) ? "[]" : sym_text(t)
    elseif k === GND
        v = lk_value(t)
        v isa AbstractString && return "s\"" * String(v) * "\""
        v isa Integer && return "$v"
        v isa AbstractFloat && return "$v"
        return "?$(typeof(v))"
    end
    h = child(t, 1)
    return (is_nil(h) ? "[]" : sym_text(h)) * "(" *
           join([_ag_enc(child(t, i), seen) for i in 2:nchildren(t)], ",") * ")"
end

# the swipl side: the MOD3b driver (consult, then every answer of each t_<id>/1, `enc`oded)
const _AG_DRIVER = raw"""
enc(T) :- enc(T, [], _).
enc(V, S0, S) :- var(V), !, ( vidx(S0, V, 0, I) -> S = S0 ; length(S0, I), append(S0, [V], S) ), format("V~w", [I]).
enc(T, S, S) :- T == [], !, write('[]').
enc(T, S, S) :- atom(T), !, write(T).
enc(T, S, S) :- string(T), !, format("s\"~w\"", [T]).
enc(T, S, S) :- integer(T), !, format("~w", [T]).
enc(T, S, S) :- float(T), !, format("~w", [T]).
enc(T, S0, S) :- compound_name_arity(T, N, A),
    write(N), format("(", []), encargs(1, A, T, S0, S), write(')').
encargs(I, A, _, S, S) :- I > A, !.
encargs(I, A, T, S0, S) :- arg(I, T, X), enc(X, S0, S1), ( I < A -> write(',') ; true ),
    I1 is I+1, encargs(I1, A, T, S1, S).
vidx([X|_], V, I, I) :- X == V, !.
vidx([_|Xs], V, I0, I) :- I1 is I0+1, vidx(Xs, V, I1, I).
fz_pred(N) :-
    format("~w", [N]), functor(G, N, 1),
    catch(findnsols(50, G, G, Gs), _, Gs = [exception]),
    forall(member(S, Gs), ( S == exception -> write(' exception') ; write(' '), enc(S) )), nl.
fz_run(File, Ns) :-
    catch(( consult(File), S = ok ), E, S = exc(E)),
    ( S == ok -> writeln(ok) ; S = exc(B), write('exc '), enc(B), nl ),
    forall(member(N, Ns), fz_pred(N)).
"""
function _ag_swipl_lines(path::String, names::Vector{String})::Vector{String}
    out = mktempdir() do d
        f = joinpath(d, "drv.pl")
        write(
            f,
            _AG_DRIVER * ":- initialization((fz_run('$path', [" * join(names, ",") *
            "]), halt)).\n"
        )
        read(
            pipeline(setenv(`swipl -q $f`, "LC_ALL" => "C"); stdin=devnull, stderr=devnull),
            String
        )
    end
    return String.(split(chomp(out), '\n'; keepempty=false))
end

# the program: one clause per shape of arg/3 in a body; `ag_off/1` and `ag_infd/2` switch the flag `vmi_builtin` around a goal
const _AG_PROGRAM = raw"""
ag_c1(T, X) :- arg(1, T, X0), X = X0.
ag_c2(T, X) :- arg(2, T, X0), X = X0.
ag_c3(T, X) :- arg(3, T, X0), X = X0.
ag_c0(T, X) :- arg(0, T, X0), X = X0.
ag_cm1(T, X) :- arg(-1, T, X0), X = X0.
ag_cbig(T, X) :- arg(100000000000000000000, T, X0), X = X0.
ag_cmax(T, X) :- arg(144115188075855871, T, X0), X = X0.
ag_v(I, T, X) :- arg(I, T, X0), X = X0.
ag_s3(T, V) :- arg(1, T, V).
ag_s3v(I, T, V) :- arg(I, T, V).
ag_c2c(X) :- arg(1, f(a, b), X0), X = X0.
ag_f2(X) :- arg(1, T, X0), X = X0-T.
ag_f1(T, X) :- arg(I, T, X0), X = I-X0.
ag_nd(I, X) :- T = f(a, b, c), arg(I, T, X0), X = I-X0.
ag_void(T) :- arg(1, T, _).
ag_two(T, X, Y) :- arg(1, T, X0), arg(2, T, Y0), X = X0, Y = Y0.
ag_use(T, X) :- arg(1, T, X0), arg(1, X0, X1), X = X1.
ag_dup(T, X) :- arg(1, T, X0), arg(2, T, X0), X = X0.
ag_det(T, X) :- arg(1, T, X0), !, X = X0.
ag_lk(X) :- T = f(_, b), arg(1, T, X0), X0 = 1, T = f(X, _).
ag_lk2(X) :- T = f(Y0, b), arg(1, T, X0), Y0 = 2, X = X0.
ag_last(T, X0) :- arg(1, T, X0).
ag_inf(G, D) :- statistics(inferences, I0), ( call(G) -> true ), statistics(inferences, I1), D is I1-I0.
ag_infd(G, R) :-
    ag_inf(G, D1), set_prolog_flag(vmi_builtin, false), ag_inf(G, D2),
    set_prolog_flag(vmi_builtin, true), R is D2-D1.
ag_infr(G, R) :- ag_infd(true, B), ag_infd(G, D), R is D-B.
ag_off(G) :-
    set_prolog_flag(vmi_builtin, false),
    (   catch(G, E, (set_prolog_flag(vmi_builtin, true), throw(E)))
    ->  set_prolog_flag(vmi_builtin, true)
    ;   set_prolog_flag(vmi_builtin, true), fail
    ).
"""

