"The program and cases as one file; the case predicates' names."
function _ag_file()::Tuple{String, Vector{String}}
    names = ["t_$(id)" for (id, _) in _AG_CASES]
    text =
        _AG_PROGRAM * join([
            "t_$(id)(R) :- catch(($g), error(SsuE, _), R = raised(SsuE)).\n" for
            (id, g) in _AG_CASES
        ])
    f = joinpath(mktempdir(), "arginl.pl")
    write(f, text)
    return f, names
end

"The kernel's lines for `names` after consulting `path`, as the driver writes swipl's."
function _ag_kernel(path::String, names::Vector{String})
    gd = LK.PL_global_data{_AG}()
    ld = LK.PL_local_data{_AG}(gd)
    st, ball, _ = LK.load_file!(gd, ld, path)
    out = [st === :ok ? "ok" : "exc " * _ag_enc(ball::_AG)]
    for name in names
        proc = LK.isCurrentProcedure(sym_key(_ags(name)), 1, LK.MODULE_user(gd))
        if proc === nothing || !LK.isDefinedProcedure(gd, proc)
            push!(out, "$name undefined")
            continue
        end
        sols = String[]
        fid = LK.PL_open_foreign_frame(ld)
        a = LK.PL_new_term_refs(ld, 1)
        LK.putSlotValue!(ld, a + 1, mk_var(_AG, LK.fresh_var_keys!(1)), LK.PutVarMap())
        qid = LK.PL_open_query(
            gd, ld, nothing, LK.PL_Q_CATCH_EXCEPTION | LK.PL_Q_EXT_STATUS, proc, a
        )
        n = 0
        while (n += 1) <= 50
            rc = LK.PL_next_solution(gd, ld, qid)
            if rc == LK.PL_S_TRUE || rc == LK.PL_S_LAST
                push!(
                    sols,
                    _ag_enc(mk_expr(_AG, _AG[_ags(name), lk_answers(ld, (a:a)...)...]))
                )
                rc == LK.PL_S_LAST && break
            elseif rc == LK.PL_S_EXCEPTION
                push!(sols, "exception")
                break
            else
                break
            end
        end
        LK.PL_close_query(ld, qid)
        LK.PL_close_foreign_frame(ld, fid)
        push!(out, "$name" * join(" " .* sols))
    end
    return out
end

@testset "arg/3 inline in a body as swipl's (B_ARG_CF, B_ARG_VF; ARGINL)" begin
    f, names = _ag_file()
    kl = _ag_kernel(f, names)
    @test length(kl) == length(_AG_PINNED)
    for (k, p) in zip(kl, _AG_PINNED)
        k == p || println(stderr, "  ours  ", k, "\n  swipl ", p)
        @test k == p
    end
    # not vacuous: the rows answer values, error terms, the empty list, and several answers; the pins hold each kind, so the comparison
    # can pass and can fail
    @test count(l -> occursin("raised(", l), _AG_PINNED) >= 20
    @test count(l -> occursin("(a)", l) || occursin(",a)", l), _AG_PINNED) >= 20
    @test count(l -> endswith(l, "([])"), _AG_PINNED) >= 10
    @test any(l -> startswith(l, "t_g_vfenum ") && occursin("-b", l), _AG_PINNED)
    # the g_* rows and the o_* rows (vmi_builtin false) of one goal give ONE answer: the inline form changes the route, not the answer
    ids = [id for (id, _) in _AG_CASES]
    pin = Dict{String, String}()
    for l in _AG_PINNED[2:end]
        name, ans = split(l, ' '; limit=2)
        pin[name] = replace(ans, "t_g_" => "t_", "t_o_" => "t_")
    end
    for id in ids
        startswith(id, "g_") || continue
        @test pin["t_g_" * id[3:end]] == pin["t_o_" * id[3:end]]
    end
end

@testset "the pins are swipl's (live, when swipl is on PATH)" begin
    swipl = get(ENV, "LOGICKERNEL_NO_SWIPL", "") == "1" ? nothing : Sys.which("swipl")
    # the pinned table is the driver's whole output (the inert-testset guard: an assertion either way)
    @test length(_AG_PINNED) == length(_AG_CASES) + 1
    if swipl === nothing
        @info "ARGINL LIVE CHECK NOT RUN: `swipl` is not on PATH here. It runs in tools/run_tests.sh and CI."
    else
        f, names = _ag_file()
        @test _ag_swipl_lines(f, names) == _AG_PINNED
    end
end
